script:
function process(ctx) {
    var vars = ctx.vars || {};
    var dialogColor = color(vars.dialogColor, "#9D5960");
    var actionColor = color(vars.actionColor, "#334E52");
    var dialogBackground = color(vars.dialogBackground, "");
    var actionBackground = color(vars.actionBackground, "");
    var specialMarker = String.fromCharCode(0xE000) + "LEGADO_SPECIAL_";

    // 只处理三类中的前两类：对话、对话后的角色行为。
    // 普通旁白和其他正文不做样式包裹，保持原样。
    var quotePairs = [
        [0x201C, 0x201D],
        [0x2018, 0x2019],
        [0x300C, 0x300D],
        [0x300E, 0x300F],
        [0xFE41, 0xFE42],
        [0xFE43, 0xFE44],
        [0x301D, 0x301E],
        [0x22, 0x22],
        [0x27, 0x27]
    ];

    function color(value, fallback) {
        var text = value == null ? "" : String(value).replace(/^\s+|\s+$/g, "");
        if (text === "" && fallback === "") return "";
        return /^#[0-9a-fA-F]{6}$/.test(text) ? text : fallback;
    }

    function enabled(value) {
        var text = value == null ? "" : String(value).replace(/^\s+|\s+$/g, "").toLowerCase();
        return text === "true" || text === "1" || text === "yes" || text === "on";
    }

    function sizeTag(value) {
        var text = value == null ? "" : String(value).replace(/^\s+|\s+$/g, "").toLowerCase();
        if (text === "small") return ["<small>", "</small>"];
        if (text === "big" || text === "large") return ["<big>", "</big>"];
        if (text === "x-large" || text === "xlarge") return ["<font size=\"5\">", "</font>"];
        return ["", ""];
    }

    function isHighSurrogate(code) {
        return code >= 0xD800 && code <= 0xDBFF;
    }

    function isLowSurrogate(code) {
        return code >= 0xDC00 && code <= 0xDFFF;
    }

    function escapeHtml(value) {
        var source = String(value);
        var output = [];
        var i;
        for (i = 0; i < source.length; i++) {
            var code = source.charCodeAt(i);
            if (isHighSurrogate(code) && i + 1 < source.length) {
                var low = source.charCodeAt(i + 1);
                if (isLowSurrogate(low)) {
                    var codePoint = (code - 0xD800) * 0x400 + (low - 0xDC00) + 0x10000;
                    output.push("&#x" + codePoint.toString(16).toUpperCase() + ";");
                    i++;
                    continue;
                }
            }
            if (code === 38) output.push("&amp;");
            else if (code === 60) output.push("&lt;");
            else if (code === 62) output.push("&gt;");
            else if (code === 34) output.push("&quot;");
            else if (code === 39) output.push("&#39;");
            else output.push(source.charAt(i));
        }
        return output.join("");
    }

    function isWordChar(value) {
        return value != null && /[A-Za-z0-9_]/.test(value);
    }

    function isApostropheInWord(text, index) {
        return text.charAt(index) === "'" &&
            isWordChar(text.charAt(index - 1)) &&
            isWordChar(text.charAt(index + 1));
    }

    function closeForOpen(current) {
        var code = current.charCodeAt(0);
        var i;
        for (i = 0; i < quotePairs.length; i++) {
            if (quotePairs[i][0] === code) return String.fromCharCode(quotePairs[i][1]);
        }
        return null;
    }

    // 只收集完整的最外层引号范围；内层引号归入外层，不单独染色。
    function findOutermostQuotes(text) {
        var stack = [];
        var ranges = [];
        var i;
        for (i = 0; i < text.length; i++) {
            var current = text.charAt(i);
            if (current === "'" && isApostropheInWord(text, i)) continue;

            // 对称英文引号先判断闭合，避免结束引号再次入栈。
            if (stack.length > 0 && current === stack[stack.length - 1].close) {
                var item = stack.pop();
                if (stack.length === 0) {
                    ranges.push({ start: item.start, end: i + 1 });
                }
                continue;
            }

            var close = closeForOpen(current);
            if (close != null) {
                stack.push({ open: current, close: close, start: i });
            }
        }
        return ranges;
    }

    function applyStyle(text, colorValue, backgroundValue, prefix) {
        var html = text;
        var fontSize = sizeTag(vars[prefix + "Size"]);
        if (fontSize[0] !== "") html = fontSize[0] + html + fontSize[1];
        if (enabled(vars[prefix + "Strike"])) html = "<s>" + html + "</s>";
        if (enabled(vars[prefix + "Underline"])) html = "<u>" + html + "</u>";
        if (enabled(vars[prefix + "Italic"])) html = "<i>" + html + "</i>";
        if (enabled(vars[prefix + "Bold"])) html = "<b>" + html + "</b>";
        if (backgroundValue !== "") {
            var bgTag = "epubbg" + backgroundValue.substring(1);
            html = "<" + bgTag + ">" + html + "</" + bgTag + ">";
        }
        if (colorValue !== "") html = '<font color="' + colorValue + '">' + html + "</font>";
        return html;
    }

    function styled(text, colorValue, backgroundValue, prefix) {
        return applyStyle(escapeHtml(text), colorValue, backgroundValue, prefix);
    }

    function hasVisibleAction(text) {
        return /[^\s，。！？、；：,.!?;:…「」『』“”‘’"'（）()【】[\]{}<>]/.test(String(text));
    }

    function findActionEnd(text, start, limit) {
        var i;
        for (i = start; i < limit; i++) {
            var current = text.charAt(i);
            // 行为句在句号、问号或感叹号处结束；逗号等连接词不截断。
            if (current === "。" || current === "！" || current === "？" || current === "!" || current === "?") {
                return i + 1;
            }
            if (current === "\n" || current === "\r") return i;
        }
        return limit;
    }

    function renderParagraph(text) {
        if (text.indexOf(specialMarker) >= 0) return text;

        var ranges = findOutermostQuotes(text);
        // 没有完整对话：普通旁白和其他正文完全不变。
        if (ranges.length === 0) return text;

        var output = [];
        var last = 0;
        var i;
        for (i = 0; i < ranges.length; i++) {
            var range = ranges[i];
            // 引号前正文不是角色行为，保持不变。
            output.push(escapeHtml(text.substring(last, range.start)));
            output.push(styled(text.substring(range.start, range.end), dialogColor, dialogBackground, "dialog"));
            last = range.end;

            // 只把紧跟在对话后的第一个行为/动作句染色；后面的普通正文保持原样。
            var nextStart = i + 1 < ranges.length ? ranges[i + 1].start : text.length;
            var actionEnd = findActionEnd(text, last, nextStart);
            var action = text.substring(last, actionEnd);
            if (hasVisibleAction(action)) {
                output.push(styled(action, actionColor, actionBackground, "action"));
            } else {
                output.push(escapeHtml(action));
            }
            last = actionEnd;
        }
        // 最后一个行为句之后的普通旁白不处理。
        if (last < text.length) output.push(escapeHtml(text.substring(last)));
        return "<usehtml>" + output.join("") + "</usehtml>";
    }

    return ctx.paragraphs.map(function(paragraph) {
        if (!paragraph || paragraph.text == null || String(paragraph.text).replace(/^\s+|\s+$/g, "") === "") {
            return null;
        }
        return {
            index: paragraph.index,
            text: renderParagraph(String(paragraph.text))
        };
    });
}
